        if is_header_footer(lines[i]):
            continue
        if RE_ROW.match(t):
            continue
        if t.startswith('[') and t.endswith(']'):
            continue
        parts.append(t)
    label = clean_field_label(" ".join(parts))
    return label

def cluster_by_rows(lines, y_tol=3.0):
    # Group indices by approximate y0 (row bands)
