        y = ln.y0
        if last_y is None or abs(y - last_y) <= y_tol:
            current.append(i)
            last_y = y if last_y is None else (last_y + y) / 2.0
        else:
            rows.append(current)
            current = [i]
            last_y = y
    if current:
        rows.append(current)
